import { A, L } from "./helpers.mjs";

export const lessons = [
  L(24, "Before joining tables, know how they relate and what one row means. This is called the grain, and it prevents most join mistakes.", [
    "One-to-many means one row here links to many rows there: one customer has many orders.",
    "The foreign key lives on the many side: orders stores customer_id.",
    "The grain is what one row represents: one row of order_items is one product in one order.",
    "To check a relationship, group by the key and count rows per value.",
  ], "shop", "SELECT customer_id, COUNT(*) AS orders\nFROM orders\nGROUP BY customer_id;", "Some customers have several orders, which shows that customers to orders is one-to-many."),
  L(25, "INNER JOIN combines rows from two tables wherever a condition matches.", [
    "FROM a JOIN b ON a.key = b.other_key is the usual form. JOIN means INNER JOIN.",
    "Rows with no match on either side are left out.",
    "Short aliases keep queries readable: FROM orders o JOIN customers c.",
    "Prefix column names with the table when both tables have a column of that name.",
  ], "shop", "SELECT o.id, c.name, o.order_date\nFROM orders o\nJOIN customers c ON c.id = o.customer_id;", "Each order finds its customer through customer_id. Noor has no orders, so she doesn't appear."),
  L(26, "LEFT JOIN keeps every row from the left table, even when nothing matches on the right.", [
    "The table after FROM is the left table, and the table after LEFT JOIN is the right.",
    "When nothing matches, the right table's columns are NULL.",
    "To count matches, use COUNT(right_column), not COUNT(*), so unmatched rows count as 0.",
    "Choose the left table by asking which rows must all appear.",
  ], "shop", "SELECT c.name, COUNT(o.id) AS orders\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id, c.name;", "Noor stays in the result with 0 orders, which an inner join would have lost."),
  L(27, "With a LEFT JOIN, where you put a condition changes the result.", [
    "A condition in ON decides which right rows match, and left rows all stay.",
    "A condition in WHERE runs after the join and removes rows, including unmatched ones.",
    "WHERE right.column = value removes NULL rows, turning a left join into an inner join.",
    "To filter the right table and keep every left row, put the condition in ON.",
  ], "shop", "SELECT c.name, o.id AS shipped_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped';", "Every customer stays. Customers without a shipped order show NULL, including those with only other statuses."),
  L(28, "An anti-join finds rows with no match, such as customers who have never ordered.", [
    "LEFT JOIN the other table, then keep rows where its key IS NULL.",
    "Test the right table's key, because a key can't be NULL in a real match.",
    "Check the direction: which table's rows do you want?",
    "The same pattern finds broken links, such as orders pointing to deleted customers.",
  ], "shop", "SELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;", "Only customers with no matching order have a NULL order id."),
  L(29, "A join repeats rows, and that can silently inflate totals.", [
    "Joining one row to three matches gives three rows, so summing a column from the one side counts it three times.",
    "Compare row counts before and after a join to spot this.",
    "COUNT(DISTINCT key) counts the real items after a join.",
    "To be safe, summarise the many side first, then join the result.",
  ], "shop", "SELECT COUNT(*) AS joined_rows, COUNT(DISTINCT o.id) AS real_orders\nFROM orders o\nJOIN order_items i ON i.order_id = o.id;", "Each order repeats once per item, so counting rows overstates the number of orders."),
  L(30, "A self join connects a table to itself, using two different aliases.", [
    "Use it when rows point to other rows in the same table, such as employees and managers.",
    "Aliases act like two copies of the table: employees e and employees m.",
    "It also compares rows with each other, such as each day with the day before.",
    "Use LEFT JOIN if rows with no match must stay, such as the top manager.",
  ], "staff", "SELECT e.name AS employee, m.name AS manager\nFROM employees e\nJOIN employees m ON m.id = e.manager_id;", "Each employee finds their manager's row. Those with no valid manager drop out of this inner join."),
  L(31, "CROSS JOIN pairs every row in one table with every row in another. It has no matching condition.", [
    "The result has the row counts multiplied together, so it can get large.",
    "It's useful for creating every possible combination, such as each student with each course.",
    "A LEFT JOIN from that grid then fills in what happened, leaving 0 where nothing did.",
    "An accidental missing ON has the same effect, which is usually a bug.",
  ], "school", "SELECT s.name, c.title, COUNT(e.id) AS attempts\nFROM students s\nCROSS JOIN courses c\nLEFT JOIN enrolments e ON e.student_id = s.id AND e.course_id = c.id\nGROUP BY s.id, s.name, c.id, c.title;", "Every student and course pair appears, including pairs with zero attempts."),
  L(32, "Joining several tables is just one join after another, each adding a table.", [
    "Each new JOIN needs its own ON linking it to a table already in the query.",
    "Follow the keys like a path: customers to orders to order_items to products.",
    "Build it one join at a time and check the rows at each step.",
    "If any step must keep unmatched rows, later joins usually must be LEFT JOINs too.",
  ], "shop", "SELECT c.name, p.name AS product, i.quantity\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items i ON i.order_id = o.id\nJOIN products p ON p.id = i.product_id;", "The query walks from customer to product through two linking tables."),
];

export const assignments = [
  A("s24-01", "shop", "Orders per customer", "Show each customer_id and how many orders it has, as orders. This reveals the one-to-many link. Replace the ___.", "Group by the foreign key.", "SELECT customer_id, COUNT(*) AS orders FROM orders GROUP BY customer_id;", [["SELECT customer_id, COUNT(*) AS orders FROM orders GROUP BY id;", "Groups by order"], ["SELECT customer_id, COUNT(*) AS orders FROM orders;", "Doesn't group"]], { starter: "SELECT customer_id, COUNT(*) AS orders\nFROM orders\nGROUP BY ___;", recalls: [20] }),
  A("s24-02", "shop", "Items per order", "Show each order_id and how many rows it has in order_items, as line_items.", "One row is one product in one order.", "SELECT order_id, COUNT(*) AS line_items FROM order_items GROUP BY order_id;", [["SELECT order_id, SUM(quantity) AS line_items FROM order_items GROUP BY order_id;", "Adds units, not rows"], ["SELECT product_id, COUNT(*) AS line_items FROM order_items GROUP BY product_id;", "Groups by product"]]),
  A("s24-03", "school", "Many on the other side", "A student can have many enrolments. Show the student_id of students with more than one enrolment.", "Filter the groups.", "SELECT student_id FROM enrolments GROUP BY student_id HAVING COUNT(*) > 1;", [["SELECT student_id FROM enrolments GROUP BY student_id;", "Keeps everyone"], ["SELECT id FROM enrolments GROUP BY id HAVING COUNT(*) > 1;", "An id is unique, so this is empty"]], { recalls: [20], alt: "+ INSERT INTO enrolments VALUES (15, 8, 5, 50, '2024-spring');" }),
  A("s24-04", "app", "Sessions per user", "Show each user_id and its number of sessions, as sessions.", "sessions.user_id is the foreign key.", "SELECT user_id, COUNT(*) AS sessions FROM sessions GROUP BY user_id;", [["SELECT user_id, COUNT(*) AS sessions FROM sessions GROUP BY session_date;", "Groups by date"], ["SELECT id, COUNT(*) AS sessions FROM sessions GROUP BY id;", "Groups by session"]], { recalls: [3] }),
  A("s24-05", "shop", "What one row means", "One order can have many rows in order_items. Show the row count as item_rows, and the number of different orders as orders.", "COUNT(DISTINCT order_id) counts real orders.", "SELECT COUNT(*) AS item_rows, COUNT(DISTINCT order_id) AS orders FROM order_items;", [["SELECT COUNT(*) AS item_rows, COUNT(*) AS orders FROM order_items;", "Treats each row as an order"], ["SELECT COUNT(DISTINCT product_id) AS item_rows, COUNT(DISTINCT order_id) AS orders FROM order_items;", "Counts products instead of rows"]], { recalls: [3] }),
  A("s24-06", "shop", "Fix the grain", "This should show how many times each product was sold, as times_sold, with one row per product_id. It runs but the grain is wrong. Fix it.", "Group by what each result row should represent.", "SELECT product_id, COUNT(*) AS times_sold FROM order_items GROUP BY product_id;", [["SELECT product_id, COUNT(*) AS times_sold FROM order_items;", "Doesn't group"], ["SELECT product_id, SUM(quantity) AS times_sold FROM order_items GROUP BY product_id;", "Adds units instead"]], { starter: "SELECT product_id, COUNT(*) AS times_sold\nFROM order_items\nGROUP BY order_id;" }),
  A("s24-07", "school", "Many-to-many", "Students and courses connect through enrolments. Show each course_id and how many different students it has, as students.", "A student can retake a course, so use DISTINCT.", "SELECT course_id, COUNT(DISTINCT student_id) AS students FROM enrolments GROUP BY course_id;", [["SELECT course_id, COUNT(*) AS students FROM enrolments GROUP BY course_id;", "Counts retakes twice"], ["SELECT student_id, COUNT(DISTINCT course_id) AS students FROM enrolments GROUP BY student_id;", "Groups by student"]], { recalls: [3] }),
  A("s24-08", "shop", "Customer per month", "Show each customer_id and month like 2024-01 as month, with their number of orders as orders. One result row is one customer in one month.", "Group by two values.", "SELECT customer_id, strftime('%Y-%m', order_date) AS month, COUNT(*) AS orders FROM orders GROUP BY customer_id, month;", [["SELECT customer_id, strftime('%Y-%m', order_date) AS month, COUNT(*) AS orders FROM orders GROUP BY customer_id;", "Merges a customer's months"], ["SELECT customer_id, strftime('%Y-%m', order_date) AS month, COUNT(*) AS orders FROM orders GROUP BY month;", "Merges customers"]], { recalls: [20], alt: "+ INSERT INTO orders VALUES (14, 7, '2024-02-02', 'shipped');" }),

  A("s25-01", "shop", "Your first join", "Show each order's id and the name of its customer. Replace the ___ with the join condition.", "Match orders.customer_id with customers.id.", "SELECT orders.id, customers.name FROM orders JOIN customers ON customers.id = orders.customer_id;", [["SELECT orders.id, customers.name FROM orders JOIN customers ON customers.id = orders.id;", "Matches on the order's own id"], ["SELECT orders.id, customers.name FROM orders JOIN customers;", "Pairs every order with every customer"]], { starter: "SELECT orders.id, customers.name\nFROM orders\nJOIN customers ON ___;" }),
  A("s25-03", "staff", "Using aliases", "Show each employee's name and their department's name as department. Use the aliases e and d.", "FROM employees e JOIN departments d.", "SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.department_id;", [["SELECT e.name, e.name AS department FROM employees e JOIN departments d ON d.id = e.department_id;", "Shows the employee's name twice"], ["SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.id;", "Joins on the wrong column"]], { recalls: [3] }),
  A("s25-04", "school", "Who's enrolled", "Show each enrolment's grade and the name of its student.", "Join enrolments to students.", "SELECT s.name, e.grade FROM enrolments e JOIN students s ON s.id = e.student_id;", [["SELECT s.name, e.grade FROM enrolments e JOIN students s ON s.id = e.course_id;", "Uses course_id"], ["SELECT e.student_id, e.grade FROM enrolments e;", "Doesn't show names"]], { recalls: [3] }),
  A("s25-05", "cafe", "Unmatched rows vanish", "Show each customer's name and order item. Orders pointing to an unknown customer and customers with no orders won't appear. This is how an inner join behaves.", "Use a plain JOIN.", "SELECT c.name, o.item FROM customers c JOIN orders o ON o.customer_id = c.id;", [["SELECT c.name, o.item FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;", "Keeps customers without orders"], ["SELECT c.name, o.item FROM orders o LEFT JOIN customers c ON o.customer_id = c.id;", "Keeps orders without customers"]], { recalls: [3] }),
  A("s25-06", "shop", "Fix the missing link", "This should show each order item's product name and quantity, but it gives far too many rows. Fix it.", "The join has no condition, so every row pairs with every product.", "SELECT p.name, i.quantity FROM order_items i JOIN products p ON p.id = i.product_id;", [["SELECT p.name, i.quantity FROM order_items i JOIN products p ON p.id = i.order_id;", "Joins on the wrong column"], ["SELECT i.product_id, i.quantity FROM order_items i;", "Doesn't show names"]], { starter: "SELECT p.name, i.quantity\nFROM order_items i\nJOIN products p;" }),
  A("s25-07", "shop", "Line value", "Show each order item's order_id, the product name, and price times quantity as line_value.", "Calculate using columns from both tables.", "SELECT i.order_id, p.name, p.price * i.quantity AS line_value FROM order_items i JOIN products p ON p.id = i.product_id;", [["SELECT i.order_id, p.name, p.price AS line_value FROM order_items i JOIN products p ON p.id = i.product_id;", "Ignores quantity"], ["SELECT i.order_id, p.name, p.cost * i.quantity AS line_value FROM order_items i JOIN products p ON p.id = i.product_id;", "Uses cost"]], { recalls: [12], decimals: 2 }),
  A("s25-08", "shop", "Revenue per category", "Show each product category and its total revenue as revenue, using price times quantity, highest first. Include every order, whatever its status.", "Join, then group.", "SELECT p.category, SUM(p.price * i.quantity) AS revenue FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category ORDER BY revenue DESC;", [["SELECT p.category, SUM(p.price) AS revenue FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category ORDER BY revenue DESC;", "Ignores quantity"], ["SELECT p.category, SUM(p.price * i.quantity) AS revenue FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category ORDER BY revenue;", "Sorts lowest first"]], { recalls: [12, 20], decimals: 2 }),

  A("s26-01", "shop", "Keep every customer", "Show every customer's name and their order id as order_id. Customers with no orders must stay. Replace the ___.", "The table that must keep all its rows comes first.", "SELECT c.name, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;", [["SELECT c.name, o.id AS order_id FROM customers c JOIN orders o ON o.customer_id = c.id;", "Drops customers with no orders"], ["SELECT c.name, o.id AS order_id FROM orders o LEFT JOIN customers c ON o.customer_id = c.id;", "Keeps orders, not customers"]], { starter: "SELECT c.name, o.id AS order_id\nFROM customers c\n___ JOIN orders o ON o.customer_id = c.id;" }),
  A("s26-02", "staff", "Departments and staff", "Show every department's name as department, and each employee's name as employee. Departments with no staff must stay.", "Start FROM departments.", "SELECT d.name AS department, e.name AS employee FROM departments d LEFT JOIN employees e ON e.department_id = d.id;", [["SELECT d.name AS department, e.name AS employee FROM departments d JOIN employees e ON e.department_id = d.id;", "Drops empty departments"], ["SELECT d.name AS department, e.name AS employee FROM employees e LEFT JOIN departments d ON e.department_id = d.id;", "Keeps employees, not departments"]]),
  A("s26-03", "shop", "Counting with zeros", "Show each customer's name and number of orders, as orders. Customers with no orders must show 0.", "COUNT a column from the right table.", "SELECT c.name, COUNT(o.id) AS orders FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", [["SELECT c.name, COUNT(*) AS orders FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", "COUNT(*) counts the empty row as 1"], ["SELECT c.name, COUNT(o.id) AS orders FROM customers c JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", "Drops customers with no orders"]], { recalls: [18, 20] }),
  A("s26-04", "school", "Every course's enrolments", "Show each course's title and its average grade as average, rounded to 1 decimal. Courses with no grades show NULL.", "AVG over no values gives NULL.", "SELECT c.title, ROUND(AVG(e.grade), 1) AS average FROM courses c LEFT JOIN enrolments e ON e.course_id = c.id GROUP BY c.id, c.title;", [["SELECT c.title, ROUND(AVG(e.grade), 1) AS average FROM courses c JOIN enrolments e ON e.course_id = c.id GROUP BY c.id, c.title;", "Drops courses without enrolments"], ["SELECT c.title, AVG(e.grade) AS average FROM courses c LEFT JOIN enrolments e ON e.course_id = c.id GROUP BY c.id, c.title;", "Doesn't round"]], { recalls: [20] }),
  A("s26-05", "shop", "Zero instead of NULL", "Show each product's name and total units sold, as units. Products that never sold must show 0, not NULL.", "SUM over nothing is NULL, so use COALESCE.", "SELECT p.name, COALESCE(SUM(i.quantity), 0) AS units FROM products p LEFT JOIN order_items i ON i.product_id = p.id GROUP BY p.id, p.name;", [["SELECT p.name, SUM(i.quantity) AS units FROM products p LEFT JOIN order_items i ON i.product_id = p.id GROUP BY p.id, p.name;", "Shows NULL"], ["SELECT p.name, COALESCE(SUM(i.quantity), 0) AS units FROM products p JOIN order_items i ON i.product_id = p.id GROUP BY p.id, p.name;", "Drops unsold products"]], { recalls: [17, 9], alt: "+ INSERT INTO products VALUES (10, 'Vase', 'Home', 5.0, 2.0);" }),
  A("s26-06", "staff", "Fix the lost rows", "This should show every employee's name and department as department, including employees with no department, but one is missing. Fix it.", "An inner join drops unmatched rows.", "SELECT e.name, d.name AS department FROM employees e LEFT JOIN departments d ON d.id = e.department_id;", [["SELECT e.name, d.name AS department FROM departments d LEFT JOIN employees e ON d.id = e.department_id;", "Keeps departments instead"], ["SELECT e.name, e.department_id AS department FROM employees e;", "Doesn't show department names"]], { starter: "SELECT e.name, d.name AS department\nFROM employees e\nJOIN departments d ON d.id = e.department_id;" }),
  A("s26-07", "staff", "Name the gap", "Show each employee's name and department as department, using the text Unassigned for employees with no department.", "COALESCE works on join results.", "SELECT e.name, COALESCE(d.name, 'Unassigned') AS department FROM employees e LEFT JOIN departments d ON d.id = e.department_id;", [["SELECT e.name, d.name AS department FROM employees e LEFT JOIN departments d ON d.id = e.department_id;", "Leaves NULL"], ["SELECT e.name, COALESCE(d.name, 'Unassigned') AS department FROM employees e JOIN departments d ON d.id = e.department_id;", "Drops employees with no department"]], { recalls: [9, 17] }),
  A("s26-08", "staff", "Department report", "Show every department's name as department, its staff count as staff, and its total salary as total_salary, with 0 for empty departments. Sort by department.", "Count and sum from the right table, with COALESCE.", "SELECT d.name AS department, COUNT(e.id) AS staff, COALESCE(SUM(e.salary), 0) AS total_salary FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id, d.name ORDER BY department;", [["SELECT d.name AS department, COUNT(*) AS staff, COALESCE(SUM(e.salary), 0) AS total_salary FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id, d.name ORDER BY department;", "COUNT(*) shows 1 for empty departments"], ["SELECT d.name AS department, COUNT(e.id) AS staff, SUM(e.salary) AS total_salary FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id, d.name ORDER BY department;", "Shows NULL for empty departments"]], { recalls: [17, 18] }),

  A("s27-01", "shop", "Filter in ON", "Show every customer's name and their shipped order's id as shipped_order. Customers with no shipped order must stay, showing NULL. Replace the ___.", "Add the status check to the ON condition.", "SELECT c.name, o.id AS shipped_order FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped';", [["SELECT c.name, o.id AS shipped_order FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status = 'shipped';", "WHERE removes customers with none"], ["SELECT c.name, o.id AS shipped_order FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;", "Includes other statuses"]], { starter: "SELECT c.name, o.id AS shipped_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND ___;" }),
  A("s27-02", "staff", "Departments' top earners", "Show every department's name as department and the name of any employee in it earning over 90000, as earner. Departments with no such employee stay with NULL.", "Put the salary check in ON.", "SELECT d.name AS department, e.name AS earner FROM departments d LEFT JOIN employees e ON e.department_id = d.id AND e.salary > 90000;", [["SELECT d.name AS department, e.name AS earner FROM departments d LEFT JOIN employees e ON e.department_id = d.id WHERE e.salary > 90000;", "Removes departments without one"], ["SELECT d.name AS department, e.name AS earner FROM departments d LEFT JOIN employees e ON e.department_id = d.id;", "Ignores the salary"]], { recalls: [6] }),
  A("s27-03", "shop", "When WHERE is right", "Show every customer's name and order id as order_id for orders with the status shipped only. Here, customers without a shipped order should be removed.", "WHERE removes those rows on purpose.", "SELECT c.name, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status = 'shipped';", [["SELECT c.name, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped';", "Keeps customers without one"], ["SELECT c.name, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;", "Includes other statuses"]], { recalls: [6] }),
  A("s27-04", "school", "Autumn results", "Show every student's name and their grades from the 2024-autumn term. Students with no autumn enrolment stay with a NULL grade.", "The term check goes in ON.", "SELECT s.name, e.grade FROM students s LEFT JOIN enrolments e ON e.student_id = s.id AND e.term = '2024-autumn';", [["SELECT s.name, e.grade FROM students s LEFT JOIN enrolments e ON e.student_id = s.id WHERE e.term = '2024-autumn';", "Removes students with no autumn enrolment"], ["SELECT s.name, e.grade FROM students s LEFT JOIN enrolments e ON e.student_id = s.id;", "Includes other terms"]], { recalls: [6], alt: "+ UPDATE enrolments SET term = '2024-autumn' WHERE id = 14;" }),
  A("s27-05", "shop", "Counting a subset", "Show each customer's name and how many shipped orders they have, as shipped. Customers with none must show 0.", "Filter in ON, then COUNT a right-table column.", "SELECT c.name, COUNT(o.id) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped' GROUP BY c.id, c.name;", [["SELECT c.name, COUNT(o.id) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status = 'shipped' GROUP BY c.id, c.name;", "Removes customers with none"], ["SELECT c.name, COUNT(*) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped' GROUP BY c.id, c.name;", "COUNT(*) shows 1 for none"]], { recalls: [9] }),
  A("s27-06", "shop", "Fix the disappearing rows", "This should show every product's name and how many units sold in order 4, as units, keeping unsold products with NULL. It has the condition in the wrong place. Fix it.", "Move the condition to ON.", "SELECT p.name, i.quantity AS units FROM products p LEFT JOIN order_items i ON i.product_id = p.id AND i.order_id = 4;", [["SELECT p.name, i.quantity AS units FROM products p LEFT JOIN order_items i ON i.product_id = p.id;", "Includes other orders"], ["SELECT p.name, i.quantity AS units FROM products p JOIN order_items i ON i.product_id = p.id AND i.order_id = 4;", "Drops unsold products"]], { starter: "SELECT p.name, i.quantity AS units\nFROM products p\nLEFT JOIN order_items i ON i.product_id = p.id\nWHERE i.order_id = 4;", recalls: [4], alt: "+ UPDATE order_items SET order_id = 4 WHERE order_id = 11;" }),
  A("s27-07", "app", "Sessions in a window", "Show every user's username and the number of their sessions on or after 2024-01-04, as recent. Users with none must show 0.", "Put the date check in ON.", "SELECT u.username, COUNT(s.id) AS recent FROM users u LEFT JOIN sessions s ON s.user_id = u.id AND s.session_date >= '2024-01-04' GROUP BY u.id, u.username;", [["SELECT u.username, COUNT(s.id) AS recent FROM users u LEFT JOIN sessions s ON s.user_id = u.id WHERE s.session_date >= '2024-01-04' GROUP BY u.id, u.username;", "Removes users with none"], ["SELECT u.username, COUNT(s.id) AS recent FROM users u LEFT JOIN sessions s ON s.user_id = u.id GROUP BY u.id, u.username;", "Ignores the date"]], { recalls: [16] }),
  A("s27-08", "shop", "Filters on both sides", "For customers from Rome only, show each name and their shipped order count, as shipped. A Rome customer with none shows 0.", "Filter customers in WHERE and orders in ON.", "SELECT c.name, COUNT(o.id) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped' WHERE c.city = 'Rome' GROUP BY c.id, c.name;", [["SELECT c.name, COUNT(o.id) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped' GROUP BY c.id, c.name;", "Includes every city"], ["SELECT c.name, COUNT(o.id) AS shipped FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE c.city = 'Rome' AND o.status = 'shipped' GROUP BY c.id, c.name;", "Removes Rome customers with none"]], { recalls: [6], alt: "UPDATE customers SET city = 'Rome' WHERE id IN (1, 5); UPDATE customers SET city = 'Lima' WHERE id IN (2, 4);" }),

  A("s28-01", "shop", "Customers without orders", "Show the name of customers who have never placed an order. Replace the ___.", "Keep rows where the right table's key is NULL.", "SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", [["SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id;", "Finds customers with orders"], ["SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id = NULL;", "= NULL never matches"]], { starter: "SELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE ___;" }),
  A("s28-02", "staff", "Empty departments", "Show the name of departments with no employees.", "Same pattern, starting from departments.", "SELECT d.name FROM departments d LEFT JOIN employees e ON e.department_id = d.id WHERE e.id IS NULL;", [["SELECT d.name FROM departments d JOIN employees e ON e.department_id = d.id;", "Finds departments with staff"], ["SELECT e.name FROM employees e WHERE e.department_id IS NULL;", "Finds employees with no department"]], { recalls: [9] }),
  A("s28-03", "shop", "Never sold", "Show the name of products that don't appear in any order item.", "Start from products.", "SELECT p.name FROM products p LEFT JOIN order_items i ON i.product_id = p.id WHERE i.product_id IS NULL;", [["SELECT p.name FROM products p JOIN order_items i ON i.product_id = p.id;", "Finds sold products"], ["SELECT p.name FROM order_items i LEFT JOIN products p ON i.product_id = p.id WHERE p.id IS NULL;", "Looks the wrong way round"]], { recalls: [26], alt: "+ INSERT INTO products VALUES (10, 'Vase', 'Home', 5.0, 2.0);" }),
  A("s28-04", "school", "Unused courses", "Show the title of courses with no enrolments.", "Check the enrolment id for NULL.", "SELECT c.title FROM courses c LEFT JOIN enrolments e ON e.course_id = c.id WHERE e.id IS NULL;", [["SELECT c.title FROM courses c JOIN enrolments e ON e.course_id = c.id;", "Finds courses with enrolments"], ["SELECT c.title FROM courses c LEFT JOIN enrolments e ON e.course_id = c.id WHERE e.grade IS NULL;", "A real enrolment can have no grade"]], { alt: "+ INSERT INTO courses VALUES (9, 'Latin', 'Arts');" }),
  A("s28-05", "cafe", "Orders with a broken link", "Show the item of orders whose customer_id matches no customer.", "Start from orders this time.", "SELECT o.item FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE c.id IS NULL;", [["SELECT o.item FROM orders o JOIN customers c ON c.id = o.customer_id;", "Finds valid orders"], ["SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", "Finds customers instead"]], { recalls: [9] }),
  A("s28-06", "shop", "Fix the test", "This should find customers with no orders, but returns nothing because it tests the wrong column. Fix it.", "Test a column from the right table.", "SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", [["SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;", "Removes the filter"], ["SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", "An inner join has no NULL matches"]], { starter: "SELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE c.id IS NULL;" }),
  A("s28-07", "shop", "No shipped orders", "Show the name of customers with no shipped order. Customers with only other statuses count as having none.", "Filter in ON, then test for NULL.", "SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'shipped' WHERE o.id IS NULL;", [["SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;", "Misses customers with only other statuses"], ["SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status <> 'shipped';", "Keeps customers with shipped orders too"]], { recalls: [9] }),
  A("s28-08", "shop", "Visits without purchases", "Show each customer city and how many of its customers never ordered, as inactive. Only list cities with at least one.", "Anti-join, then group.", "SELECT c.city, COUNT(*) AS inactive FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL GROUP BY c.city;", [["SELECT c.city, COUNT(*) AS inactive FROM customers c GROUP BY c.city;", "Counts every customer"], ["SELECT c.city, COUNT(o.id) AS inactive FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL GROUP BY c.city;", "Counting a NULL column gives 0"]], { recalls: [18, 20] }),

  A("s29-01", "shop", "See the repetition", "Join orders to order_items, then show the joined row count as joined_rows and the number of different orders as real_orders. Replace the ___.", "COUNT(DISTINCT o.id) counts real orders.", "SELECT COUNT(*) AS joined_rows, COUNT(DISTINCT o.id) AS real_orders FROM orders o JOIN order_items i ON i.order_id = o.id;", [["SELECT COUNT(*) AS joined_rows, COUNT(o.id) AS real_orders FROM orders o JOIN order_items i ON i.order_id = o.id;", "Counts repeats"], ["SELECT COUNT(*) AS joined_rows FROM orders o JOIN order_items i ON i.order_id = o.id;", "Leaves out real orders"]], { starter: "SELECT COUNT(*) AS joined_rows, COUNT(___) AS real_orders\nFROM orders o\nJOIN order_items i ON i.order_id = o.id;", recalls: [10] }),
  A("s29-02", "shop", "How many orders per customer, correctly", "Show each customer_id and their number of orders, as orders, after joining to order_items. Repeats must not inflate the count.", "Count different order ids.", "SELECT o.customer_id, COUNT(DISTINCT o.id) AS orders FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", [["SELECT o.customer_id, COUNT(*) AS orders FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", "Counts order items"], ["SELECT o.customer_id, COUNT(i.order_id) AS orders FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", "Still counts repeats"]], { recalls: [10] }),
  A("s29-03", "shop", "Summarise first", "Show each customer_id and total units as units. Use a subquery in FROM to total units per order, then join to orders.", "Summarise order_items, then join the summary.", "SELECT o.customer_id, SUM(t.units) AS units FROM orders o JOIN (SELECT order_id, SUM(quantity) AS units FROM order_items GROUP BY order_id) t ON t.order_id = o.id GROUP BY o.customer_id;", [["SELECT o.customer_id, COUNT(*) AS units FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", "Counts rows, not units"], ["SELECT customer_id, COUNT(*) AS units FROM orders GROUP BY customer_id;", "Counts orders"]], { recalls: [19] }),
  A("s29-04", "school", "Students in a subject", "Show each subject and how many different students took it, as students. A retake mustn't count twice.", "Join to courses, then count distinct students.", "SELECT c.subject, COUNT(DISTINCT e.student_id) AS students FROM enrolments e JOIN courses c ON c.id = e.course_id GROUP BY c.subject;", [["SELECT c.subject, COUNT(*) AS students FROM enrolments e JOIN courses c ON c.id = e.course_id GROUP BY c.subject;", "Counts enrolments"], ["SELECT c.subject, COUNT(DISTINCT e.course_id) AS students FROM enrolments e JOIN courses c ON c.id = e.course_id GROUP BY c.subject;", "Counts courses"]], { recalls: [10] }),
  A("s29-05", "staff", "Inflated salaries", "Each department's total salary is wanted, but with a second table joined it can double. Show each department_id and its true total as total, from employees joined to departments once.", "This join is safe, as each employee matches one department.", "SELECT e.department_id, SUM(e.salary) AS total FROM employees e JOIN departments d ON d.id = e.department_id GROUP BY e.department_id;", [["SELECT e.department_id, SUM(e.salary) AS total FROM employees e JOIN departments d GROUP BY e.department_id;", "A missing ON multiplies salaries"], ["SELECT e.department_id, COUNT(e.salary) AS total FROM employees e JOIN departments d ON d.id = e.department_id GROUP BY e.department_id;", "Counts instead of adding"]], { recalls: [19] }),
  A("s29-06", "shop", "Fix the inflated total", "This should show how many different customers bought each product, as buyers, but it counts every purchase. Fix it.", "Use DISTINCT.", "SELECT i.product_id, COUNT(DISTINCT o.customer_id) AS buyers FROM order_items i JOIN orders o ON o.id = i.order_id GROUP BY i.product_id;", [["SELECT i.product_id, COUNT(o.customer_id) AS buyers FROM order_items i JOIN orders o ON o.id = i.order_id GROUP BY i.product_id;", "Counts purchases"], ["SELECT i.product_id, COUNT(DISTINCT i.order_id) AS buyers FROM order_items i JOIN orders o ON o.id = i.order_id GROUP BY i.product_id;", "Counts orders"]], { starter: "SELECT i.product_id, COUNT(o.customer_id) AS buyers\nFROM order_items i\nJOIN orders o ON o.id = i.order_id\nGROUP BY i.product_id;", recalls: [4], alt: "+ INSERT INTO order_items VALUES (11, 9, 1, NULL), (13, 9, 1, NULL);" }),
  A("s29-07", "shop", "Average order size", "Show the average units per order as avg_units, rounded to 2 decimals. Add up units first, then average those totals.", "Use a subquery in FROM.", "SELECT ROUND(AVG(units), 2) AS avg_units FROM (SELECT order_id, SUM(quantity) AS units FROM order_items GROUP BY order_id);", [["SELECT ROUND(AVG(quantity), 2) AS avg_units FROM order_items;", "Averages rows, not orders"], ["SELECT ROUND(SUM(quantity), 2) AS avg_units FROM order_items;", "Totals instead"]], { recalls: [19] }),
  A("s29-08", "shop", "Spend by city", "Show each customer city and total revenue as revenue (price times quantity), and the number of different orders as orders.", "Revenue sums item rows, and order count needs DISTINCT.", "SELECT c.city, SUM(p.price * i.quantity) AS revenue, COUNT(DISTINCT o.id) AS orders FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city;", [["SELECT c.city, SUM(p.price * i.quantity) AS revenue, COUNT(o.id) AS orders FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city;", "Counts item rows as orders"], ["SELECT c.city, SUM(p.price) AS revenue, COUNT(DISTINCT o.id) AS orders FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city;", "Ignores quantity"]], { recalls: [24], decimals: 2 }),

  A("s30-01", "staff", "Employee and manager", "Show each employee's name as employee and their manager's name as manager. Replace the ___.", "Match the manager's id with the employee's manager_id.", "SELECT e.name AS employee, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id;", [["SELECT e.name AS employee, m.name AS manager FROM employees e JOIN employees m ON e.id = m.manager_id;", "Reverses employee and manager"], ["SELECT e.name AS employee, e.name AS manager FROM employees e;", "Shows the employee twice"]], { starter: "SELECT e.name AS employee, m.name AS manager\nFROM employees e\nJOIN employees m ON ___;" }),
  A("s30-02", "app", "Who invited whom", "Show each username as invited, and the username of the user who invited them as invited_by.", "referrer_id points to another user's id.", "SELECT u.username AS invited, r.username AS invited_by FROM users u JOIN users r ON r.id = u.referrer_id;", [["SELECT u.username AS invited, r.username AS invited_by FROM users u JOIN users r ON u.id = r.referrer_id;", "Reverses the link"], ["SELECT u.username AS invited, u.referrer_id AS invited_by FROM users u;", "Shows an id, not a name"]]),
  A("s30-03", "staff", "Keep the top", "Show every employee's name as employee and their manager's name as manager. Employees without a matching manager must stay, showing NULL.", "Use LEFT JOIN.", "SELECT e.name AS employee, m.name AS manager FROM employees e LEFT JOIN employees m ON m.id = e.manager_id;", [["SELECT e.name AS employee, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id;", "Drops employees with no manager"], ["SELECT e.name AS employee, m.name AS manager FROM employees e LEFT JOIN employees m ON e.id = m.manager_id;", "Reverses the link"]]),
  A("s30-04", "weather", "Warmer than yesterday", "Show the city and reading_date of readings warmer than the same city's reading on the previous calendar day.", "Join on city and on the date minus one day.", "SELECT t.city, t.reading_date FROM readings t JOIN readings y ON y.city = t.city AND y.reading_date = date(t.reading_date, '-1 day') WHERE t.temp_c > y.temp_c;", [["SELECT t.city, t.reading_date FROM readings t JOIN readings y ON y.city = t.city AND y.id = t.id - 1 WHERE t.temp_c > y.temp_c;", "The previous row isn't always the previous day"], ["SELECT t.city, t.reading_date FROM readings t JOIN readings y ON y.reading_date = date(t.reading_date, '-1 day') WHERE t.temp_c > y.temp_c;", "Compares across cities"]], { recalls: [16, 6] }),
  A("s30-05", "staff", "Pairs on the same salary", "Find pairs of different employees with the same salary. Show name1 and name2, listing each pair once, with the lower id first.", "Using e.id < o.id removes reversed pairs and self-pairs.", "SELECT e.name AS name1, o.name AS name2 FROM employees e JOIN employees o ON e.salary = o.salary AND e.id < o.id;", [["SELECT e.name AS name1, o.name AS name2 FROM employees e JOIN employees o ON e.salary = o.salary;", "Pairs people with themselves"], ["SELECT e.name AS name1, o.name AS name2 FROM employees e JOIN employees o ON e.salary = o.salary AND e.id <> o.id;", "Lists each pair twice"]], { recalls: [7] }),
  A("s30-06", "staff", "Fix the aliases", "This should show each employee and their manager's name as manager, but it fails because the same table has no separate aliases. Fix it.", "Give each copy its own alias.", "SELECT e.name, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id;", [["SELECT e.name, e.name AS manager FROM employees e;", "Shows the employee twice"], ["SELECT e.name, m.name AS manager FROM employees e JOIN employees m ON m.id = e.id;", "Joins each person to themselves"]], { starter: "SELECT name, name AS manager\nFROM employees\nJOIN employees ON id = manager_id;" }),
  A("s30-07", "staff", "Earning more than their manager", "Show the name of employees who earn more than their manager.", "Compare the two copies in WHERE.", "SELECT e.name FROM employees e JOIN employees m ON m.id = e.manager_id WHERE e.salary > m.salary;", [["SELECT e.name FROM employees e JOIN employees m ON m.id = e.manager_id WHERE e.salary < m.salary;", "Finds those earning less"], ["SELECT m.name FROM employees e JOIN employees m ON m.id = e.manager_id WHERE e.salary > m.salary;", "Names the manager"]], { recalls: [6], alt: "+ UPDATE employees SET salary = 95000 WHERE id = 15; UPDATE employees SET salary = 60000 WHERE id = 13;" }),
  A("s30-08", "staff", "Team sizes", "Show each manager's name as manager, how many people report to them as reports, and the average salary of those reports as avg_salary, rounded to a whole number, sorted by manager.", "Group by the manager row.", "SELECT m.name AS manager, COUNT(*) AS reports, ROUND(AVG(e.salary)) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name ORDER BY manager;", [["SELECT m.name AS manager, COUNT(*) AS reports, AVG(e.salary) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name ORDER BY manager;", "Doesn't round"], ["SELECT e.name AS manager, COUNT(*) AS reports, ROUND(AVG(e.salary)) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY e.id, e.name ORDER BY manager;", "Groups by employee"]], { recalls: [20], alt: "+ UPDATE employees SET salary = 70001 WHERE id = 12;" }),

  A("s31-01", "school", "Every pairing", "Show every student's name with every course title. Replace the ___.", "CROSS JOIN needs no condition.", "SELECT s.name, c.title FROM students s CROSS JOIN courses c;", [["SELECT s.name, c.title FROM students s JOIN courses c ON c.id = s.id;", "Pairs by matching ids only"], ["SELECT s.name FROM students s;", "Leaves out courses"]], { starter: "SELECT s.name, c.title\nFROM students s\n___ JOIN courses c;" }),
  A("s31-02", "shop", "Grid size", "Show how many rows a cross join of customers and products gives, as grid_rows.", "It's the two counts multiplied.", "SELECT COUNT(*) AS grid_rows FROM customers CROSS JOIN products;", [["SELECT COUNT(*) AS grid_rows FROM customers;", "Counts customers only"], ["SELECT COUNT(*) AS grid_rows FROM customers c JOIN orders o ON o.customer_id = c.id;", "A different join"]], { recalls: [18] }),
  A("s31-03", "shop", "Every customer and status", "Show every customer's name with every different order status, as status.", "Cross join with a DISTINCT subquery.", "SELECT c.name, s.status FROM customers c CROSS JOIN (SELECT DISTINCT status FROM orders) s;", [["SELECT c.name, o.status FROM customers c JOIN orders o ON o.customer_id = c.id;", "Shows only real orders"], ["SELECT c.name, s.status FROM customers c CROSS JOIN orders s;", "Repeats statuses"]], { alt: "+ INSERT INTO orders VALUES (14, 7, '2024-04-01', 'returned');" }),
  A("s31-04", "school", "Attempts per pair", "For every student and course, show the student's name, the course title, and how many times they enrolled, as attempts. Pairs with none show 0.", "Cross join, then LEFT JOIN enrolments.", "SELECT s.name, c.title, COUNT(e.id) AS attempts FROM students s CROSS JOIN courses c LEFT JOIN enrolments e ON e.student_id = s.id AND e.course_id = c.id GROUP BY s.id, s.name, c.id, c.title;", [["SELECT s.name, c.title, COUNT(*) AS attempts FROM students s CROSS JOIN courses c LEFT JOIN enrolments e ON e.student_id = s.id AND e.course_id = c.id GROUP BY s.id, s.name, c.id, c.title;", "COUNT(*) shows 1 for none"], ["SELECT s.name, c.title, COUNT(e.id) AS attempts FROM students s JOIN enrolments e ON e.student_id = s.id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name, c.id, c.title;", "Drops pairs with none"]], { recalls: [26, 18] }),
  A("s31-05", "shop", "Empty combinations", "Show each customer's name and product name pair where that customer has never bought that product, for customer 1 only.", "Cross join, LEFT JOIN purchases, and keep NULLs.", "SELECT c.name, p.name AS product FROM customers c CROSS JOIN products p LEFT JOIN (SELECT o.customer_id, i.product_id FROM orders o JOIN order_items i ON i.order_id = o.id) b ON b.customer_id = c.id AND b.product_id = p.id WHERE c.id = 1 AND b.product_id IS NULL;", [["SELECT c.name, p.name AS product FROM customers c CROSS JOIN products p WHERE c.id = 1;", "Includes products they bought"], ["SELECT c.name, p.name AS product FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE c.id = 1;", "Finds what they did buy"]], { recalls: [28], alt: "UPDATE orders SET customer_id = 1 WHERE id = 2;" }),
  A("s31-06", "staff", "Fix the accidental cross join", "This should show each employee's name and department name as department, but it pairs everyone with everything. Fix it.", "It needs an ON condition.", "SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.department_id;", [["SELECT e.name, d.name AS department FROM employees e CROSS JOIN departments d;", "Still pairs everyone"], ["SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.id;", "Joins on the wrong column"]], { starter: "SELECT e.name, d.name AS department\nFROM employees e\nCROSS JOIN departments d;" }),
  A("s31-07", "shop", "Sales in every category per month", "For every month in orders and every product category, show month, category, and total units sold as units, with 0 for none.", "Build the grid from two DISTINCT lists.", "SELECT m.month, k.category, COALESCE(SUM(s.quantity), 0) AS units FROM (SELECT DISTINCT strftime('%Y-%m', order_date) AS month FROM orders) m CROSS JOIN (SELECT DISTINCT category FROM products) k LEFT JOIN (SELECT strftime('%Y-%m', o.order_date) AS month, p.category, i.quantity FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id) s ON s.month = m.month AND s.category = k.category GROUP BY m.month, k.category;", [["SELECT strftime('%Y-%m', o.order_date) AS month, p.category, SUM(i.quantity) AS units FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY month, p.category;", "Drops empty combinations"], ["SELECT m.month, k.category, SUM(s.quantity) AS units FROM (SELECT DISTINCT strftime('%Y-%m', order_date) AS month FROM orders) m CROSS JOIN (SELECT DISTINCT category FROM products) k LEFT JOIN (SELECT strftime('%Y-%m', o.order_date) AS month, p.category, i.quantity FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id) s ON s.month = m.month AND s.category = k.category GROUP BY m.month, k.category;", "Shows NULL instead of 0"]], { recalls: [17, 20] }),
  A("s31-08", "school", "Report card grid", "For every student and subject, show the student's name, the subject, and a label named status: Taken if they've enrolled in any course of it, otherwise Not taken.", "Cross join students with distinct subjects.", "SELECT s.name, k.subject, CASE WHEN COUNT(e.id) > 0 THEN 'Taken' ELSE 'Not taken' END AS status FROM students s CROSS JOIN (SELECT DISTINCT subject FROM courses) k LEFT JOIN courses c ON c.subject = k.subject LEFT JOIN enrolments e ON e.course_id = c.id AND e.student_id = s.id GROUP BY s.id, s.name, k.subject;", [["SELECT s.name, c.subject, 'Taken' AS status FROM students s JOIN enrolments e ON e.student_id = s.id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name, c.subject;", "Leaves out Not taken"], ["SELECT s.name, k.subject, CASE WHEN COUNT(*) > 0 THEN 'Taken' ELSE 'Not taken' END AS status FROM students s CROSS JOIN (SELECT DISTINCT subject FROM courses) k LEFT JOIN courses c ON c.subject = k.subject LEFT JOIN enrolments e ON e.course_id = c.id AND e.student_id = s.id GROUP BY s.id, s.name, k.subject;", "COUNT(*) is never 0"]], { recalls: [17, 26] }),

  A("s32-01", "shop", "Three tables", "Show each customer's name, order id as order_id, and the quantity of each item. Replace the ___ with the second join.", "Link order_items through its order_id.", "SELECT c.name, o.id AS order_id, i.quantity FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id;", [["SELECT c.name, o.id AS order_id, i.quantity FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i;", "The second join has no condition"], ["SELECT c.name, o.id AS order_id, o.id AS quantity FROM customers c JOIN orders o ON o.customer_id = c.id;", "Leaves out item quantity"]], { starter: "SELECT c.name, o.id AS order_id, i.quantity\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\n___;" }),
  A("s32-02", "shop", "Four tables", "Show each customer's name and the name of each product they bought, as product.", "Walk from customers to products through two tables.", "SELECT c.name, p.name AS product FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id;", [["SELECT c.name, p.name AS product FROM customers c JOIN products p ON p.id = c.id;", "There's no direct link"], ["SELECT c.name, i.product_id AS product FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id;", "Shows an id, not a name"]], { recalls: [24] }),
  A("s32-03", "school", "Report rows", "Show each student's name, the course title, and the grade, for every enrolment.", "enrolments connects the other two tables.", "SELECT s.name, c.title, e.grade FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id;", [["SELECT s.name, c.title, e.grade FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.student_id;", "Uses the wrong column for courses"], ["SELECT s.name, e.course_id, e.grade FROM enrolments e JOIN students s ON s.id = e.student_id;", "Doesn't show the title"]]),
  A("s32-04", "shop", "Best-selling by customer", "Show each customer's name and their total units bought, as units, sorted by units descending, then name.", "Join three tables, then group.", "SELECT c.name, SUM(i.quantity) AS units FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name ORDER BY units DESC, c.name;", [["SELECT c.name, COUNT(*) AS units FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name ORDER BY units DESC, c.name;", "Counts rows, not units"], ["SELECT c.name, SUM(i.quantity) AS units FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name ORDER BY units, c.name;", "Sorts lowest first"]], { recalls: [11, 20] }),
  A("s32-05", "shop", "Keep everyone through two joins", "Show every customer's name and their total units bought, as units, with 0 for customers who bought nothing.", "Both joins must be LEFT JOINs.", "SELECT c.name, COALESCE(SUM(i.quantity), 0) AS units FROM customers c LEFT JOIN orders o ON o.customer_id = c.id LEFT JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name;", [["SELECT c.name, COALESCE(SUM(i.quantity), 0) AS units FROM customers c LEFT JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name;", "The inner join loses unmatched customers"], ["SELECT c.name, SUM(i.quantity) AS units FROM customers c LEFT JOIN orders o ON o.customer_id = c.id LEFT JOIN order_items i ON i.order_id = o.id GROUP BY c.id, c.name;", "Shows NULL"]], { recalls: [26, 27] }),
  A("s32-06", "shop", "Fix the chain", "This should show each order's id and product name as product, but one join links to the wrong column, giving wrong rows. Fix it.", "order_items.order_id links to orders.id.", "SELECT o.id, p.name AS product FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id;", [["SELECT o.id, p.name AS product FROM orders o JOIN order_items i ON i.product_id = o.id JOIN products p ON p.id = i.product_id;", "Keeps the bad link"], ["SELECT o.id, p.name AS product FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.order_id;", "Moves the bad link"]], { starter: "SELECT o.id, p.name AS product\nFROM orders o\nJOIN order_items i ON i.product_id = o.id\nJOIN products p ON p.id = i.product_id;" }),
  A("s32-07", "shop", "Revenue from good customers", "Show the name of customers with total shipped revenue above 50, using price times quantity, and that total as revenue.", "Filter status in WHERE, and revenue in HAVING.", "SELECT c.name, SUM(p.price * i.quantity) AS revenue FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE o.status = 'shipped' GROUP BY c.id, c.name HAVING SUM(p.price * i.quantity) > 50;", [["SELECT c.name, SUM(p.price * i.quantity) AS revenue FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.id, c.name HAVING SUM(p.price * i.quantity) > 50;", "Includes other statuses"], ["SELECT c.name, SUM(p.price * i.quantity) AS revenue FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE o.status = 'shipped' GROUP BY c.id, c.name;", "Doesn't filter totals"]], { recalls: [21], decimals: 2, alt: "+ UPDATE order_items SET quantity = 2 WHERE order_id = 11 AND product_id = 7;" }),
  A("s32-08", "school", "Subject averages per year group", "Show each year_group and subject, with the average grade rounded to 1 decimal as average, sorted by year_group then subject. Use only enrolled students.", "Three tables, two grouping columns.", "SELECT s.year_group, c.subject, ROUND(AVG(e.grade), 1) AS average FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.year_group, c.subject ORDER BY s.year_group, c.subject;", [["SELECT s.year_group, c.subject, ROUND(AVG(e.grade), 1) AS average FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.year_group ORDER BY s.year_group, c.subject;", "Merges subjects"], ["SELECT s.year_group, c.subject, AVG(e.grade) AS average FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.year_group, c.subject ORDER BY s.year_group, c.subject;", "Doesn't round"]], { recalls: [11, 20] }),

  A("st05-r01", "staff", "Named departments", "Show each employee's name and their department's name as department, A to Z by employee.", "Unmatched employees don't need to appear.", "SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.department_id ORDER BY e.name;", [["SELECT e.name, d.name AS department FROM employees e LEFT JOIN departments d ON d.id = e.department_id ORDER BY e.name;", "Keeps unmatched employees"], ["SELECT e.name, d.name AS department FROM employees e JOIN departments d ON d.id = e.department_id;", "Doesn't sort"]], { skills: [25, 11], alt: "+ UPDATE employees SET name = 'Abe' WHERE id = 15;" }),
  A("st05-r02", "app", "Quiet users", "Show the username of users with no sessions.", "Find what's missing on the other side.", "SELECT u.username FROM users u LEFT JOIN sessions s ON s.user_id = u.id WHERE s.id IS NULL;", [["SELECT u.username FROM users u JOIN sessions s ON s.user_id = u.id;", "Finds active users"], ["SELECT u.username FROM users u WHERE u.referrer_id IS NULL;", "Finds uninvited users"]], { skills: [28] }),
  A("st05-r03", "school", "Student course counts", "Show every student's name and their number of enrolments as enrolments, including 0.", "Every student must appear.", "SELECT s.name, COUNT(e.id) AS enrolments FROM students s LEFT JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name;", [["SELECT s.name, COUNT(*) AS enrolments FROM students s LEFT JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name;", "Counts 1 for no enrolments"], ["SELECT s.name, COUNT(e.id) AS enrolments FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name;", "Drops students with none"]], { skills: [26] }),
  A("st05-r04", "staff", "Manager names", "Show each employee's name, and manager's name as manager, or No manager when missing.", "Keep everyone, and replace NULLs.", "SELECT e.name, COALESCE(m.name, 'No manager') AS manager FROM employees e LEFT JOIN employees m ON m.id = e.manager_id;", [["SELECT e.name, m.name AS manager FROM employees e LEFT JOIN employees m ON m.id = e.manager_id;", "Leaves NULLs"], ["SELECT e.name, COALESCE(m.name, 'No manager') AS manager FROM employees e JOIN employees m ON m.id = e.manager_id;", "Drops employees with no manager"]], { skills: [30, 17] }),
  A("st05-r05", "shop", "Cost of what sold", "Show each product category and total cost of units sold as total_cost, using cost times quantity.", "Join, multiply, and group.", "SELECT p.category, SUM(p.cost * i.quantity) AS total_cost FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category;", [["SELECT p.category, SUM(p.cost) AS total_cost FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category;", "Ignores quantity"], ["SELECT p.category, SUM(p.price * i.quantity) AS total_cost FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY p.category;", "Uses price"]], { skills: [25, 12, 20], decimals: 2 }),
  A("st05-r06", "shop", "Order counts by status", "Show every customer's name and their number of pending orders as pending, including 0.", "Decide where the status filter belongs.", "SELECT c.name, COUNT(o.id) AS pending FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'pending' GROUP BY c.id, c.name;", [["SELECT c.name, COUNT(o.id) AS pending FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status = 'pending' GROUP BY c.id, c.name;", "WHERE removes customers with none"], ["SELECT c.name, COUNT(*) AS pending FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'pending' GROUP BY c.id, c.name;", "COUNT(*) shows 1 for none"]], { skills: [27] }),
  A("st05-r07", "school", "Retakers", "Show each student's name and course title for courses they've enrolled in more than once.", "Group by the student and course.", "SELECT s.name, c.title FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name, c.id, c.title HAVING COUNT(*) > 1;", [["SELECT s.name, c.title FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name, c.id, c.title;", "Keeps everyone"], ["SELECT s.name, c.title FROM enrolments e JOIN students s ON s.id = e.student_id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name HAVING COUNT(*) > 1;", "Doesn't split by course"]], { skills: [32, 21] }),
  A("st05-r08", "app", "Referred activity", "Show each referrer's username as referrer and the total minutes of the users they invited, as minutes, for those with sessions.", "Self join, then join sessions.", "SELECT r.username AS referrer, SUM(s.minutes) AS minutes FROM users u JOIN users r ON r.id = u.referrer_id JOIN sessions s ON s.user_id = u.id GROUP BY r.id, r.username;", [["SELECT r.username AS referrer, SUM(s.minutes) AS minutes FROM users u JOIN users r ON r.id = u.referrer_id JOIN sessions s ON s.user_id = r.id GROUP BY r.id, r.username;", "Counts the referrer's own minutes"], ["SELECT r.username AS referrer, COUNT(*) AS minutes FROM users u JOIN users r ON r.id = u.referrer_id JOIN sessions s ON s.user_id = u.id GROUP BY r.id, r.username;", "Counts sessions"]], { skills: [30, 32] }),
  A("st05-r09", "shop", "Real order totals", "Show each customer_id and the number of different products they've bought, as products.", "A product can repeat across orders.", "SELECT o.customer_id, COUNT(DISTINCT i.product_id) AS products FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", [["SELECT o.customer_id, COUNT(i.product_id) AS products FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", "Counts repeats"], ["SELECT o.customer_id, COUNT(DISTINCT o.id) AS products FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id;", "Counts orders"]], { skills: [29] }),
  A("st05-r10", "weather", "Temperature jumps", "Show each city and date where the temperature rose by at least 3 degrees from the day before, with the rise as rise.", "Self join on city and the previous date.", "SELECT t.city, t.reading_date, t.temp_c - y.temp_c AS rise FROM readings t JOIN readings y ON y.city = t.city AND y.reading_date = date(t.reading_date, '-1 day') WHERE t.temp_c - y.temp_c >= 3;", [["SELECT t.city, t.reading_date, t.temp_c - y.temp_c AS rise FROM readings t JOIN readings y ON y.city = t.city AND y.reading_date = date(t.reading_date, '-1 day') WHERE t.temp_c - y.temp_c > 3;", "Leaves out exactly 3"], ["SELECT t.city, t.reading_date, t.temp_c - y.temp_c AS rise FROM readings t JOIN readings y ON y.reading_date = date(t.reading_date, '-1 day') WHERE t.temp_c - y.temp_c >= 3;", "Compares across cities"]], { skills: [30, 16], alt: "UPDATE readings SET temp_c = 5 WHERE id = 2;" }),
  A("st05-r11", "shop", "Missing combinations", "For every category and customer city, show category, city, and how many products of that category were bought by that city's customers, as bought, including 0.", "Build the grid first.", "SELECT k.category, t.city, COUNT(b.product_id) AS bought FROM (SELECT DISTINCT category FROM products) k CROSS JOIN (SELECT DISTINCT city FROM customers) t LEFT JOIN (SELECT p.category, c.city, i.product_id FROM order_items i JOIN orders o ON o.id = i.order_id JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = i.product_id) b ON b.category = k.category AND b.city = t.city GROUP BY k.category, t.city;", [["SELECT p.category, c.city, COUNT(*) AS bought FROM order_items i JOIN orders o ON o.id = i.order_id JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = i.product_id GROUP BY p.category, c.city;", "Drops empty combinations"], ["SELECT k.category, t.city, COUNT(*) AS bought FROM (SELECT DISTINCT category FROM products) k CROSS JOIN (SELECT DISTINCT city FROM customers) t LEFT JOIN (SELECT p.category, c.city, i.product_id FROM order_items i JOIN orders o ON o.id = i.order_id JOIN customers c ON c.id = o.customer_id JOIN products p ON p.id = i.product_id) b ON b.category = k.category AND b.city = t.city GROUP BY k.category, t.city;", "COUNT(*) shows 1 for none"]], { skills: [31, 26] }),
  A("st05-r12", "cafe", "Spend per person", "Show every customer's name and their total spend as spend, with 0 for no orders.", "SUM over nothing gives NULL.", "SELECT c.name, COALESCE(SUM(o.amount), 0) AS spend FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", [["SELECT c.name, SUM(o.amount) AS spend FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", "Shows NULL"], ["SELECT c.name, COALESCE(SUM(o.amount), 0) AS spend FROM customers c JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name;", "Drops customers with no orders"]], { skills: [26, 17] }),
  A("st05-r13", "staff", "Departments without bonuses", "Show the name of departments where no employee has a bonus above 0, including empty departments.", "Filter in ON, then test for NULL.", "SELECT d.name FROM departments d LEFT JOIN employees e ON e.department_id = d.id AND e.bonus > 0 WHERE e.id IS NULL;", [["SELECT d.name FROM departments d LEFT JOIN employees e ON e.department_id = d.id WHERE e.bonus IS NULL;", "An empty bonus doesn't mean everyone has none"], ["SELECT d.name FROM departments d LEFT JOIN employees e ON e.department_id = d.id WHERE e.id IS NULL;", "Finds only empty departments"]], { skills: [27, 28] }),
  A("st05-r14", "app", "Users on two devices", "Show the username of users who used more than one device.", "Count different devices per user.", "SELECT u.username FROM users u JOIN sessions s ON s.user_id = u.id GROUP BY u.id, u.username HAVING COUNT(DISTINCT s.device) > 1;", [["SELECT u.username FROM users u JOIN sessions s ON s.user_id = u.id GROUP BY u.id, u.username HAVING COUNT(s.device) > 1;", "Counts sessions"], ["SELECT u.username FROM users u JOIN sessions s ON s.user_id = u.id GROUP BY u.id, u.username;", "Keeps everyone"]], { skills: [25, 21] }),
  A("st05-r15", "shop", "Average spend per city", "Show each customer city and its average line value as avg_line (price times quantity), rounded to 2 decimals, highest first.", "Join across four tables.", "SELECT c.city, ROUND(AVG(p.price * i.quantity), 2) AS avg_line FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city ORDER BY avg_line DESC;", [["SELECT c.city, ROUND(AVG(p.price), 2) AS avg_line FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city ORDER BY avg_line DESC;", "Ignores quantity"], ["SELECT c.city, ROUND(AVG(p.price * i.quantity), 2) AS avg_line FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.city ORDER BY avg_line;", "Sorts lowest first"]], { skills: [32, 19] }),

  A("st05-c01:6", "app", "Usernames and referrers", "Show every username, and the id of the user who invited them, renamed invited_by. Users nobody invited must show NULL.", "This needs only one table, but keep all rows.", "SELECT u.username, r.id AS invited_by FROM users u LEFT JOIN users r ON r.id = u.referrer_id;", [["SELECT u.username, r.id AS invited_by FROM users u JOIN users r ON r.id = u.referrer_id;", "Drops users nobody invited"], ["SELECT u.username, u.id AS invited_by FROM users u;", "Shows their own id"]], { skills: [26, 30] }),
  A("st05-c02:7", "shop", "Sale details", "For every order item, show its product's name, the order's date, and the quantity.", "Join order_items to two other tables.", "SELECT p.name, o.order_date, i.quantity FROM order_items i JOIN products p ON p.id = i.product_id JOIN orders o ON o.id = i.order_id;", [["SELECT p.name, o.order_date, i.quantity FROM order_items i JOIN products p ON p.id = i.product_id JOIN orders o;", "A join has no condition"], ["SELECT i.product_id, o.order_date, i.quantity FROM order_items i JOIN orders o ON o.id = i.order_id;", "Doesn't show names"]], { skills: [25, 32] }),
  A("st05-c03:8", "school", "No grade yet", "A student has an unfinished enrolment when it has no grade. Show each student_id with unfinished enrolments and how many, as unfinished.", "No join is needed. Filter, then count.", "SELECT student_id, COUNT(*) AS unfinished FROM enrolments WHERE grade IS NULL GROUP BY student_id;", [["SELECT student_id, COUNT(grade) AS unfinished FROM enrolments WHERE grade IS NULL GROUP BY student_id;", "COUNT(grade) ignores NULLs"], ["SELECT student_id, COUNT(*) AS unfinished FROM enrolments GROUP BY student_id;", "Counts all enrolments"]], { skills: [9, 20] }),
  A("st05-c04:9", "weather", "Rainier than yesterday", "Show each reading's id where rainfall was higher than the same city's rainfall on the previous calendar day.", "Join on the previous date, not the previous id.", "SELECT t.id FROM readings t JOIN readings y ON y.city = t.city AND y.reading_date = date(t.reading_date, '-1 day') WHERE t.rainfall_mm > y.rainfall_mm;", [["SELECT t.id FROM readings t JOIN readings y ON y.id = t.id - 1 WHERE t.rainfall_mm > y.rainfall_mm;", "The previous row isn't the previous day"], ["SELECT t.id FROM readings t JOIN readings y ON y.city = t.city AND y.reading_date = date(t.reading_date, '-1 day') WHERE t.rainfall_mm < y.rainfall_mm;", "Finds drier days"]], { skills: [30, 16], alt: "UPDATE readings SET rainfall_mm = 3.0 WHERE id = 2; UPDATE readings SET reading_date = '2024-03-08' WHERE id = 4; INSERT INTO readings VALUES (9, 'Oslo', '2024-03-07', 1, 0.5);" }),
  A("st05-c05:10", "app", "Average session gap", "Each user's first and last session are the earliest and latest date. Show each user_id and the days between them as span, rounded to 1 decimal.", "Use MIN, MAX, and julianday.", "SELECT user_id, ROUND(julianday(MAX(session_date)) - julianday(MIN(session_date)), 1) AS span FROM sessions GROUP BY user_id;", [["SELECT user_id, ROUND(julianday(MIN(session_date)) - julianday(MAX(session_date)), 1) AS span FROM sessions GROUP BY user_id;", "Subtracts the wrong way round"], ["SELECT user_id, COUNT(*) AS span FROM sessions GROUP BY user_id;", "Counts sessions"]], { skills: [16, 19, 20] }),
  A("st05-c06:11", "shop", "Low or missing discount", "Show each product's name and discount for order items whose discount is under 1 or wasn't recorded.", "Handle missing values explicitly.", "SELECT p.name, i.discount FROM order_items i JOIN products p ON p.id = i.product_id WHERE i.discount < 1 OR i.discount IS NULL;", [["SELECT p.name, i.discount FROM order_items i JOIN products p ON p.id = i.product_id WHERE i.discount < 1;", "Drops missing discounts"], ["SELECT p.name, i.discount FROM order_items i JOIN products p ON p.id = i.product_id WHERE i.discount IS NULL;", "Drops low discounts"]], { skills: [25, 9], alt: "+ UPDATE order_items SET discount = 0.5 WHERE order_id = 12;" }),
  A("st05-c07:12", "school", "Every attempt count", "For every student and course, show student_id, name, title, and attempts, sorted by student_id then title. Pairs with none show 0.", "Grid, then LEFT JOIN, then group.", "SELECT s.id AS student_id, s.name, c.title, COUNT(e.id) AS attempts FROM students s CROSS JOIN courses c LEFT JOIN enrolments e ON e.student_id = s.id AND e.course_id = c.id GROUP BY s.id, s.name, c.id, c.title ORDER BY s.id, c.title;", [["SELECT s.id AS student_id, s.name, c.title, COUNT(*) AS attempts FROM students s CROSS JOIN courses c LEFT JOIN enrolments e ON e.student_id = s.id AND e.course_id = c.id GROUP BY s.id, s.name, c.id, c.title ORDER BY s.id, c.title;", "COUNT(*) shows 1 for none"], ["SELECT s.id AS student_id, s.name, c.title, COUNT(e.id) AS attempts FROM students s JOIN enrolments e ON e.student_id = s.id JOIN courses c ON c.id = e.course_id GROUP BY s.id, s.name, c.id, c.title ORDER BY s.id, c.title;", "Drops pairs with none"]], { skills: [31, 26, 11] }),
  A("st05-c08:13", "staff", "Managers of many", "Show the name of employees who manage at least 2 people.", "Group by manager, then look up the name.", "SELECT m.name FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name HAVING COUNT(*) >= 2;", [["SELECT m.name FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name HAVING COUNT(*) > 2;", "Leaves out exactly 2"], ["SELECT e.name FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY e.id, e.name HAVING COUNT(*) >= 2;", "Groups by employee"]], { skills: [30, 21], alt: "+ UPDATE employees SET manager_id = 13 WHERE id = 12;" }),
  A("st05-c09:14", "shop", "Shipping rate", "A customer's shipping rate is their shipped orders divided by all their orders, and 0 if they have none. Show each customer's id as customer_id and rate, rounded to 2 decimals.", "LEFT JOIN, a conditional sum, and a safe default.", "SELECT c.id AS customer_id, ROUND(COALESCE(SUM(CASE WHEN o.status = 'shipped' THEN 1.0 ELSE 0 END) / COUNT(o.id), 0), 2) AS rate FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id;", [["SELECT c.id AS customer_id, ROUND(SUM(CASE WHEN o.status = 'shipped' THEN 1 ELSE 0 END) / COUNT(o.id), 2) AS rate FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id;", "Integer division, with NULL for no orders"], ["SELECT o.customer_id, ROUND(SUM(CASE WHEN o.status = 'shipped' THEN 1.0 ELSE 0 END) / COUNT(o.id), 2) AS rate FROM orders o GROUP BY o.customer_id;", "Drops customers with no orders"]], { skills: [26, 22, 17] }),
  A("st05-c10:16", "shop", "Average price paid", "Prices vary by product. For each product, show its id as product_id and its average price paid per unit as average_price: total price times quantity, divided by total units. Products with no sales show 0. Round to 2 decimals.", "A weighted average needs SUM divided by SUM.", "SELECT p.id AS product_id, ROUND(COALESCE(SUM(p.price * i.quantity) / SUM(i.quantity), 0), 2) AS average_price FROM products p LEFT JOIN order_items i ON i.product_id = p.id GROUP BY p.id;", [["SELECT p.id AS product_id, ROUND(SUM(p.price * i.quantity) / SUM(i.quantity), 2) AS average_price FROM products p LEFT JOIN order_items i ON i.product_id = p.id GROUP BY p.id;", "Shows NULL for no sales"], ["SELECT p.id AS product_id, ROUND(COALESCE(SUM(p.price * i.quantity) / SUM(i.quantity), 0), 2) AS average_price FROM products p JOIN order_items i ON i.product_id = p.id GROUP BY p.id;", "Drops unsold products"]], { skills: [26, 19, 17] }),
  A("st05-c11:17", "school", "Average by course", "Show each course's id as course_id and its average grade, rounded to 2 decimals, as average. Ignore courses with no enrolments.", "Join, then average.", "SELECT c.id AS course_id, ROUND(AVG(e.grade), 2) AS average FROM courses c JOIN enrolments e ON e.course_id = c.id GROUP BY c.id;", [["SELECT c.id AS course_id, AVG(e.grade) AS average FROM courses c JOIN enrolments e ON e.course_id = c.id GROUP BY c.id;", "Doesn't round"], ["SELECT c.id AS course_id, ROUND(AVG(e.grade), 2) AS average FROM courses c LEFT JOIN enrolments e ON e.course_id = c.id GROUP BY c.id;", "Keeps courses with no enrolments"]], { skills: [25, 19], alt: "+ INSERT INTO enrolments VALUES (15, 8, 5, 61, '2024-spring');" }),
  A("st05-c12:30", "staff", "Report summary", "Show each manager's id as manager_id, name, their number of direct reports as reports, and the average salary of those reports rounded to a whole number as avg_salary, sorted by id.", "Self join, then group by manager.", "SELECT m.id AS manager_id, m.name, COUNT(*) AS reports, ROUND(AVG(e.salary)) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name ORDER BY m.id;", [["SELECT m.id AS manager_id, m.name, COUNT(*) AS reports, ROUND(AVG(m.salary)) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name ORDER BY m.id;", "Averages the manager's salary"], ["SELECT m.id AS manager_id, m.name, COUNT(*) AS reports, AVG(e.salary) AS avg_salary FROM employees e JOIN employees m ON m.id = e.manager_id GROUP BY m.id, m.name ORDER BY m.id;", "Doesn't round"]], { skills: [30, 19, 11], alt: "+ UPDATE employees SET salary = 70001 WHERE id = 12;" }),
  A("st05-c13:49", "shop", "February best sellers", "Show the name of products with at least 2 units sold in February 2024, and those units as units.", "Filter the date range, then total per product.", "SELECT p.name, SUM(i.quantity) AS units FROM order_items i JOIN orders o ON o.id = i.order_id JOIN products p ON p.id = i.product_id WHERE o.order_date BETWEEN '2024-02-01' AND '2024-02-29' GROUP BY p.id, p.name HAVING SUM(i.quantity) >= 2;", [["SELECT p.name, SUM(i.quantity) AS units FROM order_items i JOIN orders o ON o.id = i.order_id JOIN products p ON p.id = i.product_id GROUP BY p.id, p.name HAVING SUM(i.quantity) >= 2;", "Ignores the date"], ["SELECT p.name, SUM(i.quantity) AS units FROM order_items i JOIN orders o ON o.id = i.order_id JOIN products p ON p.id = i.product_id WHERE o.order_date BETWEEN '2024-02-01' AND '2024-02-29' GROUP BY p.id, p.name HAVING SUM(i.quantity) > 2;", "Leaves out exactly 2"]], { skills: [32, 21, 16], alt: "+ UPDATE orders SET order_date = '2024-02-29' WHERE id IN (11, 12);" }),
];
